PRAGMA foreign_keys = ON;
CREATE TABLE profiles (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), permissions TEXT NOT NULL, created_by TEXT, created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, login TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, profile_id TEXT REFERENCES profiles(id), is_master INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, must_change INTEGER NOT NULL DEFAULT 1, session_version INTEGER NOT NULL DEFAULT 0, created_by TEXT, created_at TEXT NOT NULL, CHECK(is_master=1 OR profile_id IS NOT NULL));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), version INTEGER NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, window_start INTEGER NOT NULL);
CREATE TABLE financial_accounts (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, type TEXT NOT NULL CHECK(type IN ('bank','cash')), active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE boxes (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, description TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE categories (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE subcategories (id TEXT PRIMARY KEY, category_id TEXT NOT NULL REFERENCES categories(id), name TEXT NOT NULL COLLATE NOCASE, active INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, UNIQUE(category_id,name));
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES ('adjustment_approval','direct');
CREATE TABLE operations (id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, type TEXT NOT NULL CHECK(type IN ('opening','income','expense')), movement_date TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','effective','cancelled')), account_id TEXT NOT NULL REFERENCES financial_accounts(id), box_id TEXT REFERENCES boxes(id), category_id TEXT REFERENCES categories(id), subcategory_id TEXT REFERENCES subcategories(id), amount_cents INTEGER NOT NULL CHECK(amount_cents <> 0), payment_method TEXT CHECK(payment_method IN ('cash','pix','credit','debit')), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, approved_by TEXT REFERENCES users(id), approved_at TEXT, CHECK(type='opening' OR (box_id IS NOT NULL AND category_id IS NOT NULL)), CHECK(type<>'expense' OR payment_method IS NOT NULL));
CREATE UNIQUE INDEX opening_once ON operations(account_id) WHERE type='opening' AND status<>'cancelled';
CREATE TABLE postings (id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES operations(id), account_id TEXT NOT NULL REFERENCES financial_accounts(id), box_id TEXT REFERENCES boxes(id), amount_cents INTEGER NOT NULL CHECK(amount_cents <> 0), created_at TEXT NOT NULL);
CREATE INDEX postings_account ON postings(account_id,box_id);
CREATE INDEX operations_date ON operations(movement_date,status);
CREATE TABLE audit (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), actor_master INTEGER NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, record_id TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL);
CREATE INDEX audit_date ON audit(created_at);
CREATE TRIGGER prevent_negative_cash BEFORE INSERT ON postings WHEN (SELECT type FROM financial_accounts WHERE id=NEW.account_id)='cash' AND (COALESCE((SELECT SUM(amount_cents) FROM postings WHERE account_id=NEW.account_id),0)+NEW.amount_cents)<0 BEGIN SELECT RAISE(ABORT,'CASH_NEGATIVE'); END;
CREATE TRIGGER postings_immutable_update BEFORE UPDATE ON postings BEGIN SELECT RAISE(ABORT,'IMMUTABLE_POSTING'); END;
CREATE TRIGGER postings_immutable_delete BEFORE DELETE ON postings BEGIN SELECT RAISE(ABORT,'NO_PHYSICAL_DELETE'); END;
CREATE TRIGGER audit_immutable_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'IMMUTABLE_AUDIT'); END;
CREATE TRIGGER audit_immutable_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'NO_PHYSICAL_DELETE'); END;
